                    IRValue up = new_value(fn);
                    emit_inst_w(fn, IR_SHL, up, v, s, 0, w, 0, e->loc);
                    IRValue down = new_value(fn);
                    emit_inst_w(fn, IR_SHR, down, up, s, 0, w, 0, e->loc);
                    v = down;
