        int sf = get_value_is_float(fn, x);
        int dw = e->type.kind == TY_PTR ? 8 : (e->type.width ? e->type.width : 4);
        int du = e->type.kind == TY_PTR ? 1 : e->type.is_unsigned;
        int df = (e->type.kind == TY_FLOAT);
